result:
.el-link {
  font-size: 13px;
}

.s_lt {
  font-size: 12px;
}
.echarts-container {
  display: flex;
  justify-content: space-between;
}

.pieChart {
  width: 48%;
  height: 255px;
}
.complish_bg {
  width: 28px;
  height: 28px;
}

::v-deep .el-step__head.is-process {
  .el-step__line {
    border: 0.5px dashed #C0C4CC;
    background-color: transparent;
    height: 0.1px;
  }

  .is-text {
    background: #ffffff;
    border-color: #409EFF;
    color: #409EFF;
  }
}

::v-deep .el-step__head.is-success {
  .is-text {
    background: #409EFF;
    border-color: #409EFF;
    color: white;
  }

  .el-step__line {
    border: 0.5px dashed #409EFF;
    background-color: transparent;
    height: 0.1px;
  }

  .el-step__line-inner {
    border-width: 0 !important;
    width: 0 !important;
  }
}

/deep/ .el-step.is-horizontal .el-step__line {
  border: 0.5px dashed #409EFF;
  background-color: transparent;
  height: 0.1px;
}

/deep/ .el-step__title.is-process {
  color: #409EFF;
}

.title_con {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 15px;
}

.formLabel {
  line-height: 20px;
}

::v-deep .page_form {
  .el-form-item {
    margin-bottom: 0;
  }

  .el-col {
    margin-bottom: 0;
  }

  .el-date-editor {
    width: 100%;
  }
}

.page_body {
  position: relative;
  // padding-bottom: 200px;
}
.s_empty{
  padding: 12px;
  font-size: 14px;
  color: #a1a1a1;
}
